const bytes = pm.response.stream; // Buffer of the raw body
pm.test('JPEG without any metadata segment', () => {
  pm.expect(bytes[0]).to.eql(0xFF); pm.expect(bytes[1]).to.eql(0xD8);
  let i = 2;
  while (i + 4 <= bytes.length && bytes[i] === 0xFF && bytes[i + 1] !== 0xDA) {
    const m = bytes[i + 1];
    pm.expect(m >= 0xE0 && m <= 0xEF || m === 0xFE, 'segment FF' + m.toString(16)).to.eql(false);
    i += 2 + bytes.readUInt16BE(i + 2);
  }
  pm.expect(bytes.toString('latin1').indexOf('Exif')).to.eql(-1);
});

