const b = pm.response.stream; // Buffer of the raw body
let w = 0, h = 0, i = 2;
while (i + 9 < b.length && b[i] === 0xFF) {
  const mk = b[i + 1];
  if (mk >= 0xC0 && mk <= 0xCF && mk !== 0xC4 && mk !== 0xC8 && mk !== 0xCC) { h = b.readUInt16BE(i + 5); w = b.readUInt16BE(i + 7); break; }
  i += 2 + b.readUInt16BE(i + 2);
}
pm.test('long edge is 1800 px (1800x900)', () => { pm.expect(Math.max(w, h)).to.eql(1800); pm.expect(Math.min(w, h)).to.eql(900); });
